 "content": "def transform(grid):
    """Fill horizontal gaps between repeated marker cells with marker+1."""
    from collections import Counter
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    markers = [value for value in counts if value != background]
    if not markers:
        return [row[:] for row in grid]
    marker = min(markers, key=lambda value: counts[value])
    result = [row[:] for row in grid]
    fill = (marker + 1) % 10
    for r, row in enumerate(grid):
        positions = [c for c, value in enumerate(row) if value == marker]
        for left, right in zip(positions, positions[1:]):
            for c in range(left + 1, right):
                if result[r][c] == background:
                    result[r][c] = fill
    return result
